  return request<GenerationTask>({
    url: `/mini/generate/tasks/${taskId}`,
    method: "GET",
  }).then((task) => ({
    ...task,
    resultImageUrl: resolveFileUrl(task.resultImageUrl),
    previewImageUrl: resolveFileUrl(task.previewImageUrl),
  }));
}

