function normalizeTemplateModel(value?: string): ModelValue {
  if (!value) return "g-image-2";
  const normalized = value.toLowerCase();
  if (normalized.includes("g-image") || normalized.includes("gpt-image")) {
    return "g-image-2";
  }
  return "g-image-2";
